previewCss:
.darma-loader-download-tray {
  position: relative;
  width: 40px;
  height: 48px;
}
.darma-loader-download-tray::before {
  content: "";
  position: absolute;
  bottom: 2px;
  left: 2px;
  right: 2px;
  height: 12px;
  border: 3px solid var(--loader-color, #6366f1);
  border-top: 0;
  border-radius: 0 0 5px 5px;
  box-sizing: border-box;
}
.darma-loader-download-tray i {
  position: absolute;
  top: 2px;
  left: 50%;
  width: 5px;
  height: 16px;
  margin-left: -2.5px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-download-tray-dl 1.3s ease-in-out infinite;
}
.darma-loader-download-tray i::after {
  content: "";
  position: absolute;
  bottom: -6px;
  left: 50%;
  width: 14px;
  height: 12px;
  margin-left: -7px;
  background: var(--loader-color, #6366f1);
  clip-path: polygon(50% 100%, 0 0, 100% 0);
}
@keyframes darma-loader-download-tray-dl {
  0% { top: 2px; opacity: 0; }
  20% { opacity: 1; }
  60% { top: 18px; }
  72% { top: 13px; }
  100% { top: 18px; opacity: 1; }
}

